#include <cstdint>
#include <cstddef>
#include <string>
#include <vector>
#include "raz_runtime.hpp"

struct Token {
    std::int64_t kind{};
    std::string text{};
    std::int64_t pos{};
};

struct Expr {
    std::int64_t kind{};
    std::string op{};
    std::string text{};
    std::int64_t left{};
    std::int64_t right{};
    std::string valueText{};
    std::vector<std::int64_t> args{};
};

struct Stmt {
    std::int64_t kind{};
    std::string name{};
    std::string type{};
    std::int64_t expr{};
    std::int64_t left{};
    std::int64_t right{};
    std::vector<std::int64_t> thenStmts{};
    std::vector<std::int64_t> elseStmts{};
    std::vector<std::int64_t> body{};
};

struct Param {
    std::string name{};
    std::string type{};
};

struct Field {
    std::string name{};
    std::string type{};
};

struct FunctionDef {
    std::string name{};
    std::vector<Param> params{};
    std::string returnType{};
    std::vector<std::int64_t> body{};
};

struct StructDef {
    std::string name{};
    std::vector<Field> fields{};
};

struct Program {
    std::vector<Expr> exprs{};
    std::vector<Stmt> stmts{};
    std::vector<FunctionDef> functions{};
    std::vector<StructDef> structs{};
};

struct ParserState {
    std::vector<Token> tokens{};
    std::int64_t pos{};
    std::vector<Expr> exprs{};
    std::vector<Stmt> stmts{};
    std::vector<FunctionDef> functions{};
    std::vector<StructDef> structs{};
    std::int64_t lastTokenKind{};
    std::string lastTokenText{};
    std::int64_t lastExpr{};
    std::int64_t lastStmt{};
    std::vector<std::int64_t> lastList{};
    std::vector<std::int64_t> lastArgs{};
    std::string lastType{};
    FunctionDef lastFunction{};
    StructDef lastStruct{};
};

struct EmitState {
    std::vector<std::string> lines{};
    std::int64_t temp{};
    std::int64_t label{};
    std::string lastValue{};
};

struct Binding {
    std::string name{};
    std::string type{};
};

struct SemanticState {
    bool ok{};
    std::string message{};
};

